package org.marketreview.nativeapp;
import android.content.Context;import android.view.View;import android.widget.*;import android.text.*;import org.json.*;
public final class AccountEditScreen extends LinearLayout{
 public interface Host{JSONArray loadAccounts()throws Exception;default boolean supportsAtomicCas(){return false;}default JSONObject compareAndSave(JSONObject expected,JSONObject candidate)throws Exception{throw new Exception("宿主未接原子CAS");}}
 private final Host host;private JSONArray accounts=new JSONArray();private JSONObject expected=new JSONObject(),proposal;private final Spinner choice;private final EditText name,broker,masked,cash,note;private final CheckBox editCash;private final TextView message;private final Button save;private final ScrollView formScroll;private boolean loading,active=true;
 public AccountEditScreen(Context c,Host h){super(c);host=h;setOrientation(VERTICAL);ScrollView scroll=new ScrollView(c);formScroll=scroll;LinearLayout form=new LinearLayout(c);form.setOrientation(VERTICAL);scroll.addView(form);addView(scroll,new LayoutParams(-1,0,1));choice=new Spinner(c);choice.setTag("accountEditChoice");form.addView(choice);name=field(form,"账户名称","accountEditName");broker=field(form,"券商 / 来源","accountEditBroker");masked=field(form,"脱敏账户标识","accountEditMasked");note=field(form,"账户备注","accountEditNote");note.setMinLines(3);editCash=new CheckBox(c);editCash.setText("修改手工现金余额");editCash.setTag("accountEditCashEnabled");form.addView(editCash);cash=field(form,"现金（元）","accountEditCash");cash.setHint("未记录时为空，不代表0元");message=new TextView(c);message.setTag("accountEditMessage");form.addView(message);LinearLayout buttons=new LinearLayout(c);addView(buttons);Button read=button(buttons,"重读","accountEditReload"),preview=button(buttons,"预览","accountEditPreview"),cancel=button(buttons,"取消","accountEditCancel");save=button(buttons,"保存","accountEditSave");for(EditText e:new EditText[]{name,broker,masked,cash,note})e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int count){}public void onTextChanged(CharSequence s,int a,int b,int count){changed();}public void afterTextChanged(Editable e){}});editCash.setOnCheckedChangeListener((v,on)->{cash.setEnabled(on);changed();});choice.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>v){}public void onItemSelected(AdapterView<?>v,View row,int n,long id){if(!loading&&n<accounts.length())try{if(accounts.getJSONObject(n).optString("id").equals(expected.optString("id")))return;if(back()){loading=true;try{for(int i=0;i<accounts.length();i++)if(accounts.getJSONObject(i).optString("id").equals(expected.optString("id")))choice.setSelection(i);}finally{loading=false;}return;}expected=new JSONObject(accounts.getJSONObject(n).toString());cancel();}catch(Exception e){fail(e);}}});read.setOnClickListener(v->reload());preview.setOnClickListener(v->preview());cancel.setOnClickListener(v->cancel());save.setOnClickListener(v->commit());updateSaveButton(false);reload();}
 private EditText field(LinearLayout form,String label,String tag){TextView l=new TextView(getContext());l.setText(label);form.addView(l);EditText e=new EditText(getContext());e.setTag(tag);e.setSaveEnabled(false);e.setSaveFromParentEnabled(false);e.setMinHeight(dp(48));form.addView(e);return e;}
 private Button button(LinearLayout form,String title,String tag){Button b=new Button(getContext());b.setText(title);b.setTag(tag);b.setMinHeight(dp(48));form.addView(b,new LayoutParams(0,-2,1));return b;}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private void updateSaveButton(boolean on){save.setEnabled(on);}private void changed(){if(!loading){proposal=null;updateSaveButton(false);}}private void fail(Exception e){updateSaveButton(false);message.setText(e.getMessage());}
 public void reload(){if(!active)return;try{accounts=host==null?new JSONArray():host.loadAccounts();loading=true;String[] labels=new String[accounts.length()];for(int n=0;n<labels.length;n++){JSONObject a=accounts.getJSONObject(n);AccountEditModel.draft(a);labels[n]=a.optString("name")+" · "+a.getString("id");}choice.setAdapter(new ArrayAdapter<>(getContext(),android.R.layout.simple_spinner_dropdown_item,labels));expected=accounts.length()>0?new JSONObject(accounts.getJSONObject(0).toString()):new JSONObject();loading=false;cancel();}catch(Exception e){loading=false;fail(e);}}
 public JSONObject currentDraft()throws Exception{return new JSONObject().put("name",name.getText().toString()).put("broker",broker.getText().toString()).put("maskedNumber",masked.getText().toString()).put("note",note.getText().toString()).put("cashText",cash.getText().toString()).put("editCash",editCash.isChecked());}
 public void cancel(){loading=true;proposal=null;try{if(expected.length()>0){JSONObject d=AccountEditModel.draft(expected);name.setText(d.getString("name"));broker.setText(d.getString("broker"));masked.setText(d.getString("maskedNumber"));note.setText(d.getString("note"));cash.setText(d.getString("cashText"));}editCash.setChecked(false);cash.setEnabled(false);message.setText("草稿已恢复；未写入。现金为手工余额，不是交易流水。");}catch(Exception e){fail(e);}finally{loading=false;updateSaveButton(false);}}
 public void preview(){if(!active||expected.length()==0)return;try{proposal=AccountEditModel.propose(expected,currentDraft());String text=proposal.getBoolean("changed")?"变更已预览，保存前核对。":"没有变更，不写入。";for(String key:new String[]{"name","broker","maskedNumber","note"})if(!AccountEditModel.equal(expected.opt(key),proposal.getJSONObject("candidate").opt(key)))text+="\n"+(key.equals("name")?"账户名称":key.equals("broker")?"券商 / 来源":key.equals("maskedNumber")?"脱敏标识":"账户备注")+"已变更，请在表单核对。";if(proposal.getBoolean("cashEdited"))text+="现金将记录为 "+String.format(java.util.Locale.ROOT,"%.2f",proposal.getJSONObject("candidate").getDouble("cashBalance"))+" 元。";text=(proposal.getString("warning").isEmpty()?"":proposal.getString("warning")+"\n")+text+"\n仅已有账户元信息/手工现金；其他历史与流水保留。";if(host==null||!host.supportsAtomicCas())text+="\n保存功能尚未接通，当前草稿未写入。";message.setText(text);formScroll.post(()->formScroll.fullScroll(View.FOCUS_DOWN));updateSaveButton(proposal.getBoolean("changed")&&host!=null&&host.supportsAtomicCas());}catch(Exception e){proposal=null;fail(e);}}
 public void commit(){if(!active||proposal==null||!proposal.optBoolean("changed")||host==null||!host.supportsAtomicCas())return;try{JSONObject now=AccountEditModel.propose(expected,currentDraft());if(!AccountEditModel.equal(now,proposal))throw new Exception("预览已变化，请重新预览");JSONObject result=host.compareAndSave(new JSONObject(expected.toString()),new JSONObject(proposal.getJSONObject("candidate").toString()));if(!result.getString("id").equals(expected.getString("id"))||!result.getString("type").equals(expected.getString("type")))throw new Exception("宿主返回了不同账户，未采纳");expected=new JSONObject(result.toString());for(int n=0;n<accounts.length();n++)if(accounts.getJSONObject(n).getString("id").equals(expected.getString("id")))accounts.put(n,result);cancel();message.setText("账户修改已保存；ID/原有历史保留，未生成交易。");}catch(Exception e){fail(e);}}
 public JSONObject saveState()throws Exception{return new JSONObject().put("schema","account-editor-view/v1").put("expected",new JSONObject(expected.toString())).put("draft",currentDraft());}
 public void restoreState(JSONObject s)throws Exception{
  AccountEditModel.need("account-editor-view/v1".equals(s.optString("schema")),"账户草稿状态无效");JSONObject old=s.getJSONObject("expected"),d=s.getJSONObject("draft");AccountEditModel.propose(old,d);
  loading=true;try{int at=-1;for(int i=0;i<accounts.length();i++)if(accounts.getJSONObject(i).optString("id").equals(old.getString("id")))at=i;
   if(at<0){accounts.put(new JSONObject(old.toString()));at=accounts.length()-1;}
   String[] labels=new String[accounts.length()];for(int i=0;i<labels.length;i++)labels[i]=accounts.getJSONObject(i).optString("name")+" · "+accounts.getJSONObject(i).getString("id");
   choice.setAdapter(new ArrayAdapter<>(getContext(),android.R.layout.simple_spinner_dropdown_item,labels));choice.setSelection(at);expected=new JSONObject(old.toString());
   name.setText(d.getString("name"));broker.setText(d.getString("broker"));masked.setText(d.getString("maskedNumber"));note.setText(d.getString("note"));cash.setText(d.getString("cashText"));editCash.setChecked(d.getBoolean("editCash"));cash.setEnabled(editCash.isChecked());proposal=null;updateSaveButton(false);message.setText("未保存账户草稿已恢复；请重新预览，版本冲突将拒绝保存。");
  }finally{loading=false;}
 }
 public boolean back(){try{if(expected.length()>0&&AccountEditModel.propose(expected,currentDraft()).getBoolean("changed")){message.setText("账户草稿未保存，请明确取消或预览保存后返回。");return true;}}catch(Exception e){message.setText("账户草稿尚未处理，请先取消或修正。");return true;}return false;}
 public void setDarkTheme(boolean dark){SourceHandoffPanel.styleTree(this,dark);}
 public void setActive(boolean value){active=value;if(!value){proposal=null;updateSaveButton(false);}}
}
